# Also compare styling of filled output vs input for cells we didn't touch (styles should be unchanged)
import openpyxl
from openpyxl.utils import get_column_letter
p='mimotable_batch1_0432_template_2615_input_filled.xlsx'
i='mimotable_batch1_0432_template_2615_input.xlsx'
wb=openpyxl.load_workbook(p); wi=openpyxl.load_workbook(i)
ws=wb['Sheet1']; wsi=wi['Sheet1']
bad=[]
for r in range(1,35):
    for c in range(1,13):
        for attr in ['number_format','font','border','fill','alignment','protection']:
            a=getattr(ws.cell(r,c),attr); b=getattr(wsi.cell(r,c),attr)
            # compare relevant simple fields
            if attr=='font':
                keys=['name','size','bold','italic','underline','color']
                for k in keys:
                    try:
                        av=getattr(a,k); bv=getattr(b,k)
                    except:
                        continue
                    if hasattr(av,'rgb') and hasattr(bv,'rgb'):
                        av=av.rgb; bv=bv.rgb
                    if av!=bv:
                        bad.append((get_column_letter(c)+str(r),attr,k,av,bv))
            elif attr=='border':
                for side in ['left','right','top','bottom']:
                    av=getattr(a,side); bv=getattr(b,side)
                    for k in ['style','color']:
                        avv=getattr(av,k); bvv=getattr(bv,k)
                        if hasattr(avv,'rgb') and hasattr(bvv,'rgb'):
                            avv=avv.rgb; bvv=bvv.rgb
                        if avv!=bvv:
                            bad.append((get_column_letter(c)+str(r),attr,side,k,avv,bvv))
            elif attr=='fill':
                av=a.patternType; bv=b.patternType
                if av!=bv: bad.append((get_column_letter(c)+str(r),attr,'patternType',av,bv))
                av=a.fgColor.rgb if a.fgColor else None; bv=b.fgColor.rgb if b.fgColor else None
                if av!=bv: bad.append((get_column_letter(c)+str(r),attr,'fg',av,bv))
            elif attr=='alignment':
                for k in ['horizontal','vertical','wrap_text']:
                    av=getattr(a,k); bv=getattr(b,k)
                    if av!=bv: bad.append((get_column_letter(c)+str(r),attr,k,av,bv))
print('style mismatches', len(bad))
for x in bad[:50]:
    print(x)
EOF

